R=Path(__file__).resolve().parent;O=R/'results';s=pd.read_csv(O/'summary.csv');d=pd.read_csv(O/'deltas.csv');choices=pd.read_csv(O/'model_choices.csv');runtime=pd.read_csv(O/'training_runtime.csv');receipt=json.load(open(O/'COMPLETED.json'))
order=['always_nn','cosine_gate','logistic_gate','tree_gate','selected_gate'];names=['Always NN','Cosine cutoff','Logistic gate','Shallow-tree gate','CV-selected gate'];colors=['#228875','#dca447','#8758ab','#4289bc','#263958']
