 ax.scatter(v,np.arange(len(v)),c=colors,s=100);ax.set_yticks(np.arange(len(v)));ax.set_yticklabels(names);ax.invert_yaxis();ax.set_xlabel('Macro test F1 (%)');ax.set_title(title,fontsize=12);ax.grid(axis='x',alpha=.18)
